"use strict";function e(e=new Date){return new Date(e.getTime()+288e5).toISOString().slice(0,10)}exports.beijingDate=e,exports.homeworkDays=function(t,n=new Date){const r=e(n),a=e(new Date(n.getTime()-864e5));return[...new Set([r,a,...t.map(e=>e.date)])].sort().reverse().map(e=>{var n;return{date:e,label:e===r?"今天":e===a?"昨天":e.slice(5).replace("-","月")+"日",count:(null==(n=t.find(t=>t.date===e))?void 0:n.count)??0}})};
